      {
        pp_lgca <- mplusObject( 
          TITLE = glue(
            "Class-1_pp_LGCA"),
          
          VARIABLE = glue(
            "
GROUPING = sex12(0 = female 1 = male);      
usevar = 
wfdms12 wfdms16 wfdms18 wfdms20 wfdms22 
!wfdss12 wfdss16 wfdss18 wfdss20 wfdss22
