i1 s1 | wfdms12@0 wfdms16*4 wfdms18*6 wfdms20*8 wfdms22@10;
!i2 s2 | wfdcs12@0 wfdcs16*4 wfdcs18*6 wfdcs20*8 wfdcs22@10;  
!i3 s3 | wfdds712@0 wfdds716@4 wfdds718@6 wfdds720@8 wfdds722@10;  
!i4 s4 | wfdds812@0 wfdds816@4 wfdds818@6 wfdds820@8 wfdds822@10;
i5 s5 | ces8sd12@0 ces8sd16*4 ces8sd18*6 ces8sd20*8 ces8sd22@10;  

i1 s1 i5 s5 WITH i1 s1 i5 s5;

![i1](x_mean0);
!i1(x_var0);

![s1](x_mean0);
!s1(x_var0);

![i2](w_mean0);
!i2(w_var0);

[s2](w_mean0);
s2(w_var0);

!!! Focus: intercept of ces8sd regressed on intercept of wfd
!i5 on i1 i2;
i5 on i1(b1i0);
i5 on i2(b2i0);

!!! Focus: slope of ces8sd regressed on intercept of wfd
!s5 on i1 i2 i5 s1 s2 s1s2_int;
s5 on i5 i1 i2; !!! s2 was removed due to non-convergence
s5 on s1 (b1s0);
s5 on s2 (b2s0);
s5 on s1s2_int (b3s0);

!!! control: for long trend
! time-invar
i5 s5 on edu12 urban12 prov122 prov123;
i5 s5 on cdn12 cdar12 cdsc121 cdsc122 minor12 wave ;

! time-var
i5 s5 on ageg12 pinc12 pinc212 cores12 heal121 heal123;
i5 s5 on marr12 hukou12 eco122 eco123 hwc122 hwc123 sat12 adl12 finc12;



Model male:

i1 s1 | wfdms12@0 wfdms16*4 wfdms18*6 wfdms20*8 wfdms22@10;
!i2 s2 | wfdcs12@0 wfdcs16*4 wfdcs18*6 wfdcs20*8 wfdcs22@10;  
!i3 s3 | wfdds712@0 wfdds716@4 wfdds718@6 wfdds720@8 wfdds722@10;  
!i4 s4 | wfdds812@0 wfdds816@4 wfdds818@6 wfdds820@8 wfdds822@10;
i5 s5 | ces8sd12@0 ces8sd16*4 ces8sd18*6 ces8sd20*8 ces8sd22@10;  

i1 s1 i5 s5 WITH i1 s1 i5 s5;

!s5@0;
![i1](x_mean1);
!i1(x_var1);

![s1](x_mean1);
!s1(x_var1);

![i2](w_mean1);
!i2(w_var1);

[s2](w_mean1);
s2(w_var1);

!!! Focus: intercept of ces8sd regressed on intercept of wfd
!i5 on i1 i2;
i5 on i1(b1i1);
i5 on i2(b2i1);

!!! Focus: slope of ces8sd regressed on intercept of wfd
!s5 on i1 i2 i5 s1 s2 s1s2_int;
s5 on i5 i1 i2; !!! s2 was removed due to non-convergence
s5 on s1 (b1s1);
s5 on s2 (b2s1);
s5 on s1s2_int (b3s1);

!!! control: for long trend
! time-invar
i5 s5 on edu12 urban12 prov122 prov123;
i5 s5 on cdn12 cdar12 cdsc121 cdsc122 minor12 wave ;

! time-var
i5 s5 on ageg12 pinc12 pinc212 cores12 heal121 heal123;
i5 s5 on marr12 hukou12 eco122 eco123 hwc122 hwc123 sat12 adl12 finc12;


    ",
          
          
          MODELCONSTRAINT = 
            glue(
              "
!!! i on i * i
!NEW (wiii0min wiii0lo wiii0mod wiii0hi wiii0max);
!wiii0min = b1i0 + b3i0*({wvalue_i2_min0});
!wiii0lo = b1i0 + b3i0*(w_mean0 - sqrt(w_var0));
!wiii0mod = b1i0 + b3i0*w_mean0;
!wiii0hi = b1i0 + b3i0*(w_mean0 + sqrt(w_var0));
!wiii0max = b1i0 + b3i0*({wvalue_i2_max0});

!!! s on i * i
!NEW (wiis0min wiis0lo wiis0mod wiis0hi wiis0max);
!wiis0min = b1s0 + b3s0*({wvalue_i2_min0});
!wiis0lo = b1s0 + b3s0*(w_mean0 - sqrt(w_var0));
!wiis0mod = b1s0 + b3s0*w_mean0;
!wiis0hi = b1s0 + b3s0*(w_mean0 + sqrt(w_var0));
!wiis0max = b1s0 + b3s0*({wvalue_i2_max0});

!!! i on i * i
!NEW (wiii1min wiii1lo wiii1mod wiii1hi wiii1max);
!wiii1min = b1i1 + b3i1*({wvalue_i2_min1});
!wiii1lo = b1i1 + b3i1*(w_mean1 - sqrt(w_var1));
!wiii1mod = b1i1 + b3i1*w_mean1;
!wiii1hi = b1i1 + b3i1*(w_mean1 + sqrt(w_var1));
!wiii1max = b1i1 + b3i1*({wvalue_i2_max1});

!!! s on i * i
!NEW (wiis1min wiis1lo wiis1mod wiis1hi wiis1max);
!wiis1min = b1s1 + b3s1*({wvalue_i2_min1});
!wiis1lo = b1s1 + b3s1*(w_mean1 - sqrt(w_var1));
!wiis1mod = b1s1 + b3s1*w_mean1;
!wiis1hi = b1s1 + b3s1*(w_mean1 + sqrt(w_var1));
!wiis1max = b1s1 + b3s1*({wvalue_i2_max1});

!NEW(wiiidiff wiisdiff);
!wiiidiff=b3i0-b3i1;
!wiisdiff=b3s0-b3s1;

!!! s on i * s
!NEW (wiss0min wiss0lo wiss0mod wiss0hi wiss0max);
!wiss0min = b1s0 + b3s0*({wvalue_s2_min0});
!wiss0lo = b1s0 + b3s0*(w_mean0 - sqrt(w_var0));
!wiss0mod = b1s0 + b3s0*w_mean0;
!wiss0hi = b1s0 + b3s0*(w_mean0 + sqrt(w_var0));
!wiss0max = b1s0 + b3s0*({wvalue_s2_max0});

!!! s on i * s
!NEW (wiss1min wiss1lo wiss1mod wiss1hi wiss1max);
!wiss1min = b1s1 + b3s1*({wvalue_s2_min1});
!wiss1lo = b1s1 + b3s1*(w_mean1 - sqrt(w_var1));
!wiss1mod = b1s1 + b3s1*w_mean1;
!wiss1hi = b1s1 + b3s1*(w_mean1 + sqrt(w_var1));
!wiss1max = b1s1 + b3s1*({wvalue_s2_max1});

!NEW(wissdiff);
!wissdiff=b3s0-b3s1;

!!! s on s * i
!NEW (wsis0min wsis0lo wsis0mod wsis0hi wsis0max);
!wsis0min = b1s0 + b3s0*({wvalue_i2_min0});
!wsis0lo = b1s0 + b3s0*(w_mean0 - sqrt(w_var0));
!wsis0mod = b1s0 + b3s0*w_mean0;
!wsis0hi = b1s0 + b3s0*(w_mean0 + sqrt(w_var0)); 
!wsis0max = b1s0 + b3s0*({wvalue_i2_max0});

!!! s on s * i
!NEW (wsis1min wsis1lo wsis1mod wsis1hi wsis1max);
!wsis1min = b1s1 + b3s1*({wvalue_i2_min1});
!wsis1lo = b1s1 + b3s1*(w_mean1 - sqrt(w_var1));
!wsis1mod = b1s1 + b3s1*w_mean1;
!wsis1hi = b1s1 + b3s1*(w_mean1 + sqrt(w_var1)); 
!wsis1max = b1s1 + b3s1*({wvalue_i2_max1});

!NEW(wsisdiff);
!wsisdiff=b3s0-b3s1;

!!! s on s * s
NEW (wsss0min wsss0lo wsss0mod wsss0hi wsss0max);
wsss0min = b1s0 + b3s0*({wvalue_s2_min0});
wsss0lo = b1s0 + b3s0*(w_mean0 - sqrt(w_var0));
wsss0mod = b1s0 + b3s0*w_mean0;
wsss0hi = b1s0 + b3s0*(w_mean0 + sqrt(w_var0)); 
wsss0max = b1s0 + b3s0*({wvalue_s2_max0});

!!! s on s * s
NEW (wsss1min wsss1lo wsss1mod wsss1hi wsss1max);
wsss1min = b1s1 + b3s1*({wvalue_s2_min1});
wsss1lo = b1s1 + b3s1*(w_mean1 - sqrt(w_var1));
wsss1mod = b1s1 + b3s1*w_mean1;
wsss1hi = b1s1 + b3s1*(w_mean1 + sqrt(w_var1)); 
wsss1max = b1s1 + b3s1*({wvalue_s2_max1});

NEW(wsssdiff);
wsssdiff=b3s0-b3s1;

!*
!!! range for x
NEW (x_low x_high);
x_low = x_mean - sqrt(x_var);
x_high = x_mean + sqrt(x_var);

!!! range for w
NEW (w_low w_high);
w_low = w_mean - sqrt(w_var);
w_high = w_mean + sqrt(w_var);
*!

  "),
          
          OUTPUT = 
            "tech1 tech4 tech10 tech11 tech14 sampstat patterns stdyx;",
          
          SAVEDATA = glue(
            "FILE = pp_lgca_type12_sex12_r_step2_s_mod_s_MI_TICs_MG_result.txt;
!SAVE = CPROB;"),
          
          PLOT =
            "type = plot3;",
          
          usevariables = colnames(lgca_covar_MI_tics_data), 
          rdata = lgca_covar_MI_tics_data,
          imputed = TRUE
        ) 
        
        # 构造新文件夹result_gmm路径 
        newdir <- file.path(here("interge_rela", "result_pp_lgca_continu.panel_best_clo_ces8sd_covar_time12_22"))
        # 自动创建文件夹, recursive = TRUE, 覆盖原有文件夹
        if (!dir.exists(newdir)) {
          dir.create(newdir, recursive = TRUE)
        }
        # 检查目录是否创建成功
        if (!dir.exists(newdir)) {
          stop("目录创建失败，请检查路径和权限。")
        }
        # 设定工作目录
        setwd(newdir)   
        # 指定了要执行运算的模型, 即上面定义的包含有Mplus代码的模型    
        pp_lgca_fit <- mplusModeler(pp_lgca, 
                                    dataout = "pp_lgca_type12_sex12_r_step2_s_mod_s_MI_TICs_MG.dat", 
                                    modelout = glue("pp_lgca_type12_sex12_r_step2_s_mod_s_MI_TICs_MG.inp"),
                                    check = TRUE, run = TRUE, hashfilename = FALSE, quiet = FALSE)  
      } 
    }
  }
  ### 带 XWITH的 分组回归
  # XWITH 涉及"非线性关系"必须要用ALGORITHM=INTEGRATION;
  # 多组分析GROUPING不能组合ALGORITHM=INTEGRATION;使用, 必须使用KNOWNCLASS估计
  # 尽管未找到 multiple-group LMS做三重交互的研究,但Linda muthen确实是这么建议的:
  # https://www.statmodel.com/discussion/messages/11/7276.html?1339005304
  # https://www.statmodel.com/discussion/messages/11/78.html?1588886562
  # https://www.statmodel.com/discussion/messages/14/1280.html?1599159404
  
  
  # 三步
  # 1.首先确定无条件PP-LGCM相关因子设定 在 分组模型下仍然适用(可能存在负方差)
  # 2.视为观测变量的调节变量 应该分组估计增长因子(可能不收敛导致无法获得 调节变量), 保守起见使用不分组设定估计增长因子.
  # 3.KNOWNCLASS分组估计过程中. 同一分组PP-LGCM设定下, 不同 截距 斜率之间的交互项模型 可能不收敛(额外的参数调整, 导致估计方法不一致)
  {
    ### 标准差 对 均值 的调节效应
    {
      ### 性别
      {
        # 性别
        # single group analysis
        # sex12 = 0
        {
          pp_lgca <- mplusObject( 
            TITLE = glue(
              "Class-1_pp_LGCA"),
            
            VARIABLE = glue(
              "
SUBPOPULATION = sex12 EQ 0;
usevar = 
wfdms12 wfdms16 wfdms18 wfdms20 wfdms22 
!wfdss12 wfdss16 wfdss18 wfdss20 wfdss22
