ces8sd12 ces8sd16 ces8sd18 ces8sd20 ces8sd22
;
idvariable=pid;
cluster=fid;"
            ),
            
            ANALYSIS =
              "estimator = mlr;
TYPE=COMPLEX;
!type = mixture;
!ALGORITHM=INTEGRATION;
!starts = 600 200;
!starts = 20;
!LRTBOOTSTRAP = 200;
processors = 10;
coverage = 0.005;",
            
            MODEL = 
              "
i1 s1 | wfdms12@0 wfdms16*4 wfdms18*6 wfdms20*8 wfdms22@10;
!i2 s2 | wfdss12@0 wfdss16*4 wfdss18*6 wfdss20*8 wfdss22@10;  
