      names(pp_lgca_type12_step1.data)
      
      # 对I2进行标准化
      pp_lgca_type12_step1.data <- pp_lgca_type12_step1.data %>%
        mutate(I2_std = (I2 - mean(I2, na.rm = TRUE))/sd(I2, na.rm = TRUE)) %>%
        mutate(S2_std = (S2 - mean(S2, na.rm = TRUE))/sd(S2, na.rm = TRUE))
      
      # 调节变量取值范围
      wvalue_i2_min <- min(pp_lgca_type12_step1.data$I2_std, na.rm = TRUE)
      wvalue_i2_max <- max(pp_lgca_type12_step1.data$I2_std, na.rm = TRUE)
      
      wvalue_s2_min <- min(pp_lgca_type12_step1.data$S2_std, na.rm = TRUE)
      wvalue_s2_max <- max(pp_lgca_type12_step1.data$S2_std, na.rm = TRUE)
      
