          ),
          
          DEFINE = 
            "
STANDARDIZE I2 S2;
wz_int = S2 * pinc412; ! WZ
      ",
          
          ANALYSIS =
            "estimator = mlr;
TYPE=COMPLEX;
TYPE = RANDOM;
!type = mixture;
ALGORITHM=INTEGRATION;
!INTEGRATION = MONTECARLO;
!starts = 600 200;
