wiii1 = b4i + b7i*hi_z;

!!! s on i * i
NEW (wiis0 wiis1);
wiis0 = b4s + b7s*lo_z;
wiis1 = b4s + b7s*hi_z;

!!! s on i * s
NEW (wiss0 wiss1);
