      pp_lgca_fit <- mplusModeler(pp_lgca, 
                                  dataout = "pp_lgca_type14_pinc412_r_step2_s_mod_i_MI_TICs.dat", 
                                  modelout = glue("pp_lgca_type14_pinc412_r_step2_s_mod_i_MI_TICs.inp"),
                                  check = TRUE, run = TRUE, hashfilename = FALSE, quiet = FALSE)  
    } 
    
