      pp_lgca_fit <- mplusModeler(pp_lgca, 
                                  dataout = "pp_lgca_type14_4_sex12_r_step2_i_mod_i_MI_TICs.dat", 
                                  modelout = glue("pp_lgca_type14_4_sex12_r_step2_i_mod_i_MI_TICs.inp"),
                                  check = TRUE, run = TRUE, hashfilename = FALSE, quiet = FALSE)  
    } 
    
    # i1s4_int
    {
      pp_lgca <- mplusObject( 
        TITLE = glue(
          "Class-1_pp_LGCA"),
        
        VARIABLE = glue(
          "usevar = 
  wfdms12 wfdms16 wfdms18 wfdms20 wfdms22 
!wfdcs12 wfdcs16 wfdcs18 wfdcs20 wfdcs22
