          "
STANDARDIZE I4 S4;
wz_int = I4 * edu12; ! WZ
      ",
        
        ANALYSIS =
          "estimator = mlr;
TYPE=COMPLEX;
TYPE = RANDOM;
!type = mixture;
ALGORITHM=INTEGRATION;
!INTEGRATION = MONTECARLO;
!starts = 600 200;
