STANDARDIZE I4 S4;
wz_int = I4 * pinc412; ! WZ
      ",
        
        ANALYSIS =
          "estimator = mlr;
TYPE=COMPLEX;
TYPE = RANDOM;
!type = mixture;
ALGORITHM=INTEGRATION;
