                               sprintf("%.3f", se), ")")
        ) %>% 
        filter(outcome.var %in% c("I5.ON", "S5.ON")) %>% 
        select(outcome.var, predictor.var, est_pval_se) %>% 
        pivot_wider(names_from = outcome.var, values_from = est_pval_se) %>% 
        mutate(
          # 创建辅助列 sort_group，用于排序 I1 S1 SEX11 I1SX_INT S1SX_INT
          sort_group = case_when(
            predictor.var %in% c("I2") ~ 0,
            predictor.var %in% c("S2") ~ 1,
            predictor.var %in% c("I1", "I3", "I4") ~ 0,
            predictor.var %in% c("S1", "S3", "S4") ~ 1,         
            # predictor.var %in% c("I1I2_INT","I1I3_INT","I1I4_INT","I2I1_INT","I3I1_INT","I4I1_INT") ~ 4,
            # predictor.var %in% c("I1S2_INT","I1S3_INT","I1S4_INT","I2S1_INT","I3S1_INT","I4S1_INT") ~ 5,
            # predictor.var %in% c("S1I2_INT","S1I3_INT","S1I4_INT","S2I1_INT","S3I1_INT","S4I1_INT") ~ 6,
            # predictor.var %in% c("S2S1_INT","S1S3_INT","S1S4_INT") ~ 7
            predictor.var %in% c("XW_INT","XZ_INT","WZ_INT","XWZ_INT") ~ 4,
            predictor.var %in% c("XW0","XW1") ~ 5,
            predictor.var %in% c("X0MIN","X0LO","X0MOD","X0HI","X0MAX") ~ 6,        
            predictor.var %in% c("X1MIN","X1LO","X1MOD","X1HI","X1MAX") ~ 7,
          )
        ) %>% 
        # 按照 sort_group 进行排序
        arrange(sort_group) %>% 
        select(-sort_group)
      
      
      # 2. 提取 Pseudo-R square
      r2 <- output.cesd8.type21_s2s1[["parameters"]][["r2"]]
      I5_r2 <- r2[r2$param == "I5", "est"]
      S5_r2 <- r2[r2$param == "S5", "est"]
      
      # 3. 提取模型拟合指数
      summaries <- output.cesd8.type21_s2s1[["summaries"]]
      AIC <- summaries$AIC_Mean[1]
      BIC <- summaries$BIC_Mean[1]
      CFI <- summaries$CFI_Mean[1]
      TLI <- summaries$TLI_Mean[1]
      RMSEA <- summaries$RMSEA_Mean[1]
      
      # 4. 创建拟合指数文本
      model.fit_text.type1 <- paste0("AIC=", sprintf("%.2f", AIC), 
                                     ",\n BIC=", sprintf("%.2f", BIC))
      
      # 5. 添加 Pseudo-R² 行和 Model fit index 行
      model.result.type21_s2s1 <- model.result.type21_s2s1 %>% 
        add_row(
          predictor.var = "Pseudo-R²",
          I5.ON = sprintf("%.3f", I5_r2),
          S5.ON = sprintf("%.3f", S5_r2)
        ) %>% 
        add_row(
          predictor.var = "Model fit index",
          I5.ON = model.fit_text.type1,
          S5.ON = model.fit_text.type1
        ) %>% 
        mutate(
          predictor.var.common = case_when(
            # predictor.var %in% c("I1", "I2", "I3", "I4") ~ "Intercept",
            # predictor.var %in% c("S1", "S2", "S3", "S4") ~ "Slope",
            # predictor.var %in% c("SEX12") ~ "SEX",
            # predictor.var %in% c("I1SX_INT","I2SX_INT","I3SX_INT","I4SX_INT") ~ "SEX × Intercept",
            # predictor.var %in% c("S1SX_INT","S2SX_INT","S3SX_INT","S4SX_INT") ~ "SEX × Slope",
            predictor.var == "Intercepts" ~ "Means",
            predictor.var == "Residual.Variances" ~ "Variances",
            TRUE ~ predictor.var # 默认 NA，避免杂乱值
          ))
      
      model.result.type21_s2s1  
      
      
      
      
      
      model.result.type21_i2i1
      model.result.type21_i2s1
      model.result.type21_s2i1
      model.result.type21_s2s1
      
      
      ##### 合并所有结果表
      # 按predictor.var列合并所有结果到一个数据框
      library(dplyr)
      
      # 方案1：逐步合并，每次都明确指定 suffix
      model.result.type21_all <- model.result.type21_i2i1 %>%
        select(predictor.var.common, I5.ON, S5.ON) %>%
        rename(I5.ON.II = I5.ON, S5.ON.II = S5.ON) %>%
        full_join(
          model.result.type21_i2s1 %>%
            select(predictor.var.common, I5.ON, S5.ON) %>%
            rename(I5.ON.IS = I5.ON, S5.ON.IS = S5.ON),
          by = "predictor.var.common"
        ) %>%
        full_join(
          model.result.type21_s2i1 %>%
            select(predictor.var.common, I5.ON, S5.ON) %>%
            rename(I5.ON.SI = I5.ON, S5.ON.SI = S5.ON),
          by = "predictor.var.common"
        ) %>%
        full_join(
          model.result.type21_s2s1 %>%
            select(predictor.var.common, I5.ON, S5.ON) %>%
            rename(I5.ON.SS = I5.ON, S5.ON.SS = S5.ON),
          by = "predictor.var.common"
        ) %>% 
        mutate(
          # 创建辅助列 sort_group，用于排序 I1 S1 SEX11 I1SX_INT S1SX_INT
          sort_group = case_when(
            predictor.var.common %in% c("I2") ~ 0,
            predictor.var.common %in% c("S2") ~ 1,
            predictor.var.common %in% c("I1", "I3", "I4") ~ 2,
            predictor.var.common %in% c("S1", "S3", "S4") ~ 3,         
            # predictor.var.common %in% c("I1I2_INT","I1I3_INT","I1I4_INT","I2I1_INT","I3I1_INT","I4I1_INT") ~ 4,
            # predictor.var.common %in% c("I1S2_INT","I1S3_INT","I1S4_INT","I2S1_INT","I3S1_INT","I4S1_INT") ~ 5,
            # predictor.var.common %in% c("S1I2_INT","S1I3_INT","S1I4_INT","S2I1_INT","S3I1_INT","S4I1_INT") ~ 6,
            # predictor.var.common %in% c("S1S2_INT","S1S3_INT","S1S4_INT","S2S1_INT","S3S1_INT","S4S1_INT") ~ 7,
            # # predictor.var.common %in% c("I_MIN","I_LO","I_MOD","I_HI","I_MAX") ~ 8,
            # predictor.var.common %in% c("MIN","LO","MOD","HI","MAX") ~ 9
            predictor.var.common %in% c("XW_INT","XZ_INT","WZ_INT") ~ 4,
            predictor.var.common %in% c("XWZ_INT") ~ 5,
            predictor.var.common %in% c("XW0","XW1") ~ 6,
            predictor.var.common %in% c("X0MIN","X0LO","X0MOD","X0HI","X0MAX") ~ 7,        
            predictor.var.common %in% c("X1MIN","X1LO","X1MOD","X1HI","X1MAX") ~ 8,
          )
        ) %>% 
        # 按照 sort_group 进行排序
        arrange(sort_group) %>% 
        select(-sort_group)
      
      # 查看结果(带控制变量)
      model.result.type21_all
      
      
      
      model.result.type21_all.simple <- model.result.type21_all %>%
        filter(predictor.var.common %in% 
                 c("I1","S1","I2","S2","I3","S3","I4","S4",
