          ),
          
          DEFINE = 
            "
STANDARDIZE I1 S1;
wz_int = S1 * sex12; ! WZ
      ",
          
          ANALYSIS =
            "estimator = mlr;
TYPE=COMPLEX;
TYPE = RANDOM;
!type = mixture;
ALGORITHM=INTEGRATION;
