                                    dataout = "pp_lgca_type31_edu12_r_step2_i_mod_s_MI_TICs.dat", 
                                    modelout = glue("pp_lgca_type31_edu12_r_step2_i_mod_s_MI_TICs.inp"),
                                    check = TRUE, run = TRUE, hashfilename = FALSE, quiet = FALSE)  
      } 
      
      # s3s1_int
      {
        pp_lgca <- mplusObject( 
          TITLE = glue(
            "Class-1_pp_LGCA"),
          
          VARIABLE = glue(
            "usevar = 
!wfdms12 wfdms16 wfdms18 wfdms20 wfdms22 
!wfdcs12 wfdcs16 wfdcs18 wfdcs20 wfdcs22
wfdds712 wfdds716 wfdds718 wfdds720 wfdds722
