cluster=fid;"
          ),
          
          DEFINE = 
            "
STANDARDIZE I1 S1;
wz_int = S1 * edu12; ! WZ
      ",
          
          ANALYSIS =
            "estimator = mlr;
TYPE=COMPLEX;
TYPE = RANDOM;
!type = mixture;
ALGORITHM=INTEGRATION;
!INTEGRATION = MONTECARLO;
!starts = 600 200;
!starts = 20;
!LRTBOOTSTRAP = 200;
!processors = 10;
coverage = 0.005;",
          
          MODEL = 
            "
!i1 s1 | wfdms12@0 wfdms16*4 wfdms18*6 wfdms20*8 wfdms22@10;
!i2 s2 | wfdcs12@0 wfdcs16*4 wfdcs18*6 wfdcs20*8 wfdcs22@10;  
