                                    modelout = glue("pp_lgca_type31_pinc412_r_step2_i_mod_i_MI_TICs.inp"),
                                    check = TRUE, run = TRUE, hashfilename = FALSE, quiet = FALSE)  
      } 
      
      # i3s1_int
      {
        pp_lgca <- mplusObject( 
          TITLE = glue(
            "Class-1_pp_LGCA"),
          
          VARIABLE = glue(
            "usevar = 
!wfdms12 wfdms16 wfdms18 wfdms20 wfdms22 
