      } 
      
      # s1i4_int
      {
        pp_lgca <- mplusObject( 
          TITLE = glue(
            "Class-1_pp_LGCA"),
          
          VARIABLE = glue(
            "usevar = 
!wfdms12 wfdms16 wfdms18 wfdms20 wfdms22 
