                                     ",\n BIC=", sprintf("%.2f", BIC))
      
      # 5. 添加 Pseudo-R² 行和 Model fit index 行
      model.result.type4_41_s2s1 <- model.result.type4_41_s2s1 %>% 
        add_row(
          predictor.var = "Pseudo-R²",
          I5.ON = sprintf("%.3f", I5_r2),
          S5.ON = sprintf("%.3f", S5_r2)
        ) %>% 
        add_row(
          predictor.var = "Model fit index",
          I5.ON = model.fit_text.type1,
          S5.ON = model.fit_text.type1
        ) %>% 
        mutate(
          predictor.var.common = case_when(
            # predictor.var %in% c("I1", "I2", "I3", "I4") ~ "Intercept",
            # predictor.var %in% c("S1", "S2", "S3", "S4") ~ "Slope",
            # predictor.var %in% c("SEX12") ~ "SEX",
            # predictor.var %in% c("I1SX_INT","I2SX_INT","I3SX_INT","I4SX_INT") ~ "SEX × Intercept",
            # predictor.var %in% c("S1SX_INT","S2SX_INT","S3SX_INT","S4SX_INT") ~ "SEX × Slope",
            predictor.var == "Intercepts" ~ "Means",
            predictor.var == "Residual.Variances" ~ "Variances",
            TRUE ~ predictor.var # 默认 NA，避免杂乱值
          ))
      
      model.result.type4_41_s2s1  
      
      
      
      
      
      model.result.type4_41_i2i1
      model.result.type4_41_i2s1
      model.result.type4_41_s2i1
      model.result.type4_41_s2s1
      
      
      ##### 合并所有结果表
      # 按predictor.var列合并所有结果到一个数据框
      library(dplyr)
      
      # 方案1：逐步合并，每次都明确指定 suffix
      model.result.type4_41_all <- model.result.type4_41_i2i1 %>%
        select(predictor.var.common, I5.ON, S5.ON) %>%
        rename(I5.ON.II = I5.ON, S5.ON.II = S5.ON) %>%
        full_join(
          model.result.type4_41_i2s1 %>%
            select(predictor.var.common, I5.ON, S5.ON) %>%
            rename(I5.ON.IS = I5.ON, S5.ON.IS = S5.ON),
          by = "predictor.var.common"
        ) %>%
        full_join(
          model.result.type4_41_s2i1 %>%
            select(predictor.var.common, I5.ON, S5.ON) %>%
            rename(I5.ON.SI = I5.ON, S5.ON.SI = S5.ON),
          by = "predictor.var.common"
        ) %>%
        full_join(
          model.result.type4_41_s2s1 %>%
            select(predictor.var.common, I5.ON, S5.ON) %>%
            rename(I5.ON.SS = I5.ON, S5.ON.SS = S5.ON),
          by = "predictor.var.common"
        ) %>% 
        mutate(
          # 创建辅助列 sort_group，用于排序 I1 S1 SEX11 I1SX_INT S1SX_INT
          sort_group = case_when(
            predictor.var.common %in% c("I4") ~ 0,
            predictor.var.common %in% c("S4") ~ 1,
            predictor.var.common %in% c("I1", "I2", "I3") ~ 2,
            predictor.var.common %in% c("S1", "S2", "S3") ~ 3,         
            # predictor.var.common %in% c("I1I2_INT","I1I3_INT","I1I4_INT","I2I1_INT","I3I1_INT","I4I1_INT") ~ 4,
            # predictor.var.common %in% c("I1S2_INT","I1S3_INT","I1S4_INT","I2S1_INT","I3S1_INT","I4S1_INT") ~ 5,
            # predictor.var.common %in% c("S1I2_INT","S1I3_INT","S1I4_INT","S2I1_INT","S3I1_INT","S4I1_INT") ~ 6,
            # predictor.var.common %in% c("S1S2_INT","S1S3_INT","S1S4_INT","S2S1_INT","S3S1_INT","S4S1_INT") ~ 7,
            # # predictor.var.common %in% c("I_MIN","I_LO","I_MOD","I_HI","I_MAX") ~ 8,
            # predictor.var.common %in% c("MIN","LO","MOD","HI","MAX") ~ 9
            predictor.var.common %in% c("XW_INT","XZ_INT","WZ_INT") ~ 4,
            predictor.var.common %in% c("XWZ_INT") ~ 5,
            predictor.var.common %in% c("XW0","XW1") ~ 6,
            predictor.var.common %in% c("X0MIN","X0LO","X0MOD","X0HI","X0MAX") ~ 7,        
            predictor.var.common %in% c("X1MIN","X1LO","X1MOD","X1HI","X1MAX") ~ 8,
          )
        ) %>% 
        # 按照 sort_group 进行排序
        arrange(sort_group) %>% 
        select(-sort_group)
      
      # 查看结果(带控制变量)
      model.result.type4_41_all
      
      
      
      model.result.type4_41_all.simple <- model.result.type4_41_all %>%
        filter(predictor.var.common %in% 
                 c("I1","S1","I2","S2","I3","S3","I4","S4",
                   "XW_INT","XZ_INT","WZ_INT","XWZ_INT",
                   "XW0","XW1",
                   "X0MIN","X0LO","X0MOD","X0HI","X0MAX",
                   "X1MIN","X1LO","X1MOD","X1HI","X1MAX",
                   "Means","Variances","Pseudo-R²","Model fit index","MIN","LO","MOD","HI","MAX")) %>% 
        # 将所有缺失值 NA 替换为 "-"
        mutate(
          across(everything(), as.character),  # 将所有列转换为字符型
          across(everything(), ~ ifelse(is.na(.), "— —", .))
        ) 
      
      # 查看结果(略控制变量)
      model.result.type4_41_all.simple
      
      
      
      
      ##### 使用gt()包导出表格
      model.result.type4_41_all.simple.t <- model.result.type4_41_all.simple %>%
        gt(rowname_col = "predictor.var.common",) %>%
        # tab_options(
        #   table.font.size = px(12),
        #   row_group.as_column = FALSE
        # ) %>% 
        tab_header(
          title = md("PP-LGCM PINC412_MEAN moderation effects of closeness Sib_diff4 traj on depressive traj_MI_TICs_r"),
          subtitle = md("")) %>%
        cols_label(
          predictor.var.common = md(""),
          "I5.ON.II" = md("**I5**"),
          "S5.ON.II" = md("**S5**"),
          "I5.ON.IS" = md("**I5**"),
          "S5.ON.IS" = md("**S5**"),
          "I5.ON.SI" = md("**I5**"),
          "S5.ON.SI" = md("**S5**"),
          "I5.ON.SS" = md("**I5**"),
          "S5.ON.SS" = md("**S5**")
        ) %>% 
        tab_spanner(label = "I2I1", columns = 2:3) %>% 
        tab_spanner(label = "I2S1", columns = 4:5) %>% 
        tab_spanner(label = "S2I1", columns = 6:7) %>% 
        tab_spanner(label = "S2S1", columns = 8:9) %>% 
        tab_style(
          style = cell_text(align = "center", whitespace = "pre-wrap"),
          locations = cells_body(columns = c(2:9))  # c(亲密无间型,生活照料型,经济帮助型,独立疏远型)
        )  %>%
        tab_style(
          style = cell_text(weight = "bold",),
          locations = cells_row_groups()
        )  %>%
        tab_footnote( 
          footnote = md(paste0("Notes . CFI = comparative fit index; RMSEA = root mean square error of approximation. All the control variables were included in both models. Unstandardized coeffcients are presented. Standard errors in parentheses. All models were also adjusted for number of waves in which respondents 
participated(Friedman etal., 2025). The variance of the slope for positive marital quality is constrained to be 0 due to lack of variation over time. <br>\n", 
                               "\\+ p < 0.1, * p < 0.05, ** p < 0.01, *** p < 0.001")),
          locations = cells_body(columns = "I5.ON.II",
                                 rows = 1)
        ) %>% gt::fmt_markdown(columns = everything()) 
      
      print(model.result.type4_41_all.simple.t) 
      
      # 覆盖已有文件时会报错(加入if函数提前删除重复文件，避免报错)
      
      filename.doc <- file.path(here("interge_rela", 
                                     "result_pp_lgca_continu.panel_best_clo_ces8sd_covar_time12_22",
                                     "202501020 PP-LGCM PINC412_MEAN moderation effects of closeness Sib_diff4 traj on depressive traj_MI_TICs_r.docx"))
      
      filename.png <- file.path(here("interge_rela", 
                                     "result_pp_lgca_continu.panel_best_clo_ces8sd_covar_time12_22",
                                     "202501020 PP-LGCM PINC412_MEAN moderation effects of closeness Sib_diff4 traj on depressive traj_MI_TICs_r.png"))
      
      if (file.exists(filename.doc)) {
        file.remove(filename.doc)
      }
      
      # install.packages("chromote")
      # library(chromote)
      gtsave(model.result.type4_41_all.simple.t, filename = filename.doc)
      
      Sys.setenv(CHROMOTE_CHROME = "C:/Program Files/Google/Chrome/Application/chrome.exe")
      gtsave(model.result.type4_41_all.simple.t, filename = filename.png, expand = 30, vwidth = 1200, vheight = 1000)
      
    }   
    
  }
  
  
  
  
}







































